from short_stories import S
SHORT = [
S('shared','','第一口乡音','几户湖广人把自己的酿豆办法带到新乡，集市第一次卖出不一样的饭食。旧摊户认为他们未曾参加过市亭维修，不应占据最好的铺位；乡医愿品验食物，年轻人却已在两种口味之间来回排队。',[
('集市上的新灶','新摊户愿按季交钱，旧行会仍要求由本地人担保。府署可以给短期摊牌，也可维持担保，或让各摊共同安排灶口。','给短期摊牌，准公开售食。|按旧担保办，保留本地铺位。|共同验食，按灶口分摊修亭钱。'),
('谁能用这口井','新摊户被挡在共井之外，只能另雇人取水。旧户担心客人多了会不够用，乡医提醒不洁的水会影响整个集市。','扩井共用，补取水工钱。|保留旧井，另给客摊供水。|按用量分担井钱，不按籍贯。'),
('新菜留在旧市','新摊户希望留下，旧行会提出统一价目和名字。府署可以承认不同风味，也可纳入行会，或以卫生与质量定摊牌。','保留各自风味，公开验食。|纳入旧行会，统一价目。|按卫生与成色发长期摊牌。')],['trade g-4 burghers-.02|guild p3|witness g-3','well g-6|custom g-4|audit g-3','festival p2|guild p3|medicine g-4'],'culture'),
S('shared','','借住的院落','一户迁来的人暂住旧院，院主起初只收少量柴钱，如今认为他们已有作坊，应当改收租。迁户修过屋顶，也替院主照料过老人，却没有把这些写成钱契。邻里愿作证，双方都担心争执传到行会。',[
('修过的屋顶','院主要求立即补租，迁户请求将修屋工钱抵去。府署可以核对劳作，也可维护原主的收租权，或为双方重立短契。','把修屋工钱抵租。|维护原主，给迁户短期宽限。|共同重契，明确此后的维修。'),
('院中多了一台织机','迁户添了织机，院主想收部分织货作为房钱。邻居认为作坊噪声需要另议，工匠担心新租让自己永远无法搬走。','限定房租，不分作坊货利。|准按货利收租，保护出资院主。|另租小坊，府库担保首季房钱。'),
('能不能留下门牌','迁户准备买下自己的住处，请求在门牌上写本府住户。院主愿售，旧族却认为买屋不等于取得共同乡议的名额。','按居住记录给门牌。|只认买屋，乡议仍由旧户主持。|以修路出资取得共同见证。')],['justice p2 nobles-.03|custom p3|witness g-3','trade burghers.02|contract g3|settlement g-7','open_register p-2|closed_register p3|witness g-4'],'land'),
S('shared','','渡口的两个孩子','迁户的孩子与本地孩子一同在渡口做短工，其中一个摔伤后，两家都说自己付过护工的钱。船主认为孩子只是临时帮忙，不算雇工；医者请求先把伤者送进药舍，再查谁为这一天担保。',[
('先救哪一本账','府署可以先付医钱，也可让船主按约赔付，或请两家共同作保。伤者躺在岸边，账本却还在船舱里。','先付医钱，再查雇用。|令船主赔付，暂停其短工招用。|共同照料，登记两家的费用。'),
('账里没有姓名','账本只记着“渡口小工”，没有两人的名字。书记希望按原账结案，家属请求以后每个短工都应有名。','增记短工姓名，准家属查账。|按原账处理，保留船主声名。|设渡口共用雇工簿。'),
('下一次招工','伤者恢复后想回渡口做活，家属担心再次出事。船主愿多付一点工钱，条件是不再追究旧账。府署可以明定短工责任，也可只安排一次补偿。','明定责任，训练护工。|给一次补偿，维持旧雇用。|药舍定期查伤，船帮分担费用。')],['medicine g-6|justice p2|witness g-3','audit p2|custom p3|school g-4','wages g-5|guild g-4|medicine g-5'],'medicine'),
S('shared','','由谁教孩子读书','外来匠人请求让子女进府学旁的蒙舍，旧教读说名额已给本地家族。孩子能认工账上的数字，却不懂老师要求的旧文。几名商人愿资助纸墨，条件是蒙舍也教账法。',[
('蒙舍的空位','府署可以增设教读，也可维护旧有名额，或把商人的纸墨变成共同小课。孩子的家属已经备好一份薄礼，却不知道老师是否愿收。','增设教读，准新旧户同学。|保留旧名额，给新户另找老师。|接受商人纸墨，开公共账法课。'),
('第一份试卷','孩子在算账题上答得好，旧教读认为不能因此省去礼文。商人请求按用途分课，贵族则希望维持统一选拔。','分设礼文与账法，不限出身。|按旧试卷取人，维护府学体面。|共留试卷，给老师比较教学。'),
('教读人的位置','新课吸引了更多住户，原老师希望主持权传给子弟。家属认为出钱不能换来永久名额，府署可按教读成绩择人，也可尊重旧家供养。','按教学成绩聘任。|保留旧家主持，明列公共名额。|由住户轮选教读，公账供纸墨。')],['school g-7 nobles-.03|custom g-4 p3|sponsor g-3','translation g-4 r.2|patron p3|survey g-4 r.3','school g-6 r.3|custom p4|audit g-4'],'education'),
S('shared','','迁来的祭日','几户新住民按旧乡祭日备饭，恰与本村清渠的日期相逢。领役人认为他们借礼俗逃工，新户说自己已经在别的日子出过力。乡老愿另定一日，却担心以后人人都按自家习俗请求改役。',[
('同一天的两件事','府署可允许调役，也可维护既定役日，或雇人先补渠工。不同安排都需有人承担延期或雇用的钱。','准调役，登记实出工日。|按旧日清渠，另给祭钱。|雇人补渠，保留两方祭期。'),
('祭席上的席钱','新户请求在旧亭祭祀，被要求另交席钱。掌亭者称旧户多年修亭，新户认为调役已经承担了费用。','按使用定席钱，不分新旧。|保留旧户减免，给新户宽限。|共同修亭，重新登记出资。'),
('来年的清渠簿','双方愿把调役写入下一年的簿册，领役人请求保留紧急征工。府署可以承认礼期，也可只给逐案宽免，或建立付酬替役。','承认礼期，按季调役。|保留逐案宽免，维护领役。|设付酬替役，让乡里自行筹工。')],['relief p-1|censor g-4 p3|wages g-6','witness p2|custom p3|festival g-4','translation p2|censor p4|wages g-5'],'festival'),
S('shared','','一间新药铺','外乡医者在本村开药铺，本地医者指责他未受行规。病家觉得新药价低，却担心所用药草与以前不同。两位医者都愿把治过的人列出来，家属希望比较病程，不愿只凭谁的名字更熟悉。',[
('药铺能否开门','府署可以准限期诊治，也可保护本地行规，或请两医共同会诊。病家急等药钱，任何查验都须有一处暂时取药的地方。','准限期診治，登记病程。|守旧行规，另补病家药钱。|共同会诊，分担查验。'),
('不一样的药草','一种旧乡药草确有用处，却不适合所有病人。老医者请求不得当作包治的名号，新医者同意改写药单。','公布适用病症，撤去包治之名。|由本地医者主持定方。|留药样给府学，继续比较。'),
('留下来的医者','新药铺已有固定病家，本地医者愿收他的子弟为徒，但希望铺号并入自己名下。府署可承认独立药铺，也可促成共用药舍。','承认独立铺号，公开查方。|合入旧药铺，维持行规。|设共同药舍，给两医固定酬钱。')],['medicine g-5 r.2|custom g-4 p3|survey g-5 r.3','medicine p2|guild p3|research_archive g-5 r.3','trade burghers.02|guild p4|medicine wages g-6'],'medicine'),
S('shared','','荒地上的借种','迁户用从旧乡带来的种子播下第一季田，邻村愿借种，却要求新户先参加义仓担保。种子不多，新户担心借出去后自家无粮，旧户又怕新来的田迟早要分走灌水。',[
('这一袋种子','府署可以供粮让新户留种，也可按旧仓约办，或设小块试田供两村观察。眼前的互借需要有人分担歉收风险。','供口粮，让两村共留种。|按旧仓担保，保留旧户水额。|设共同试田，府库付种钱。'),
('试田里的虫','新种有一部分遭虫，旧户认为不应继续推广，迁户指出另一块坡田结穗较好。我们可以比较田势，也可先恢复熟悉的作物。','按田势分种，记录虫害。|恢复旧种，维持仓粮稳定。|请医者与农户共同查虫。'),
('下一袋归还的种粮','借种户带回不同颜色的谷子，掌仓人要求严格按原种归还。新户认为能留足播种的好谷即可，旧仓户担心账目因此混乱。','按发芽与收成验还。|按原种验还，保护仓册。|分仓保存，教住户共同记种。')],['grain g-6|custom p3|seed survey g-7','seed r.2|guild p3|medicine g-4 r.2','survey r.25|audit p3|school g-5'],'agriculture'),
S('shared','','合开的染坊','两个不同乡籍的染户合开作坊，一家供染料，一家供劳作。头一季赚了钱，双方却对未写入契纸的试染损失有不同记忆。行会愿作保，要求这座新坊沿用本地配方与价目。',[
('亏损算谁的','府署可核对试染，认可劳作投入，也可维护最初的出资额，或让行会代为结账。不同计法会使其中一方失去继续合开的意愿。','核对劳作与试染，共担损失。|按出资额分账。|设共同账房，暂不分坊。'),
('想带走的配方','一名师傅准备另开小坊，要求带走自己试出的配方。出料的伙伴认为配方也受过自己的损失，应有使用份额。','准师傅另作，给伙伴限期补偿。|配方留在合坊，保住出资。|公开部分做法，保留特殊订货。'),
('旧坊的新学徒','两坊继续供货，却争抢同一个学徒。家属希望学徒能两处传习，行会要求固定师傅。府署可承认跨坊传习，也可维持旧收徒规矩。','准跨坊传习，明定工钱。|一师一徒，维护行规。|设共同试染课，以技艺分工。')],['justice p2|contract p3|audit g-3','trade burghers.02|guild p3|craft g-5 r.2','school g-5 r.3|guild p4|survey g-5 r.3'],'craft'),
S('shared','','同住一坡的山民','迁户在山脚养起牲畜，原来的山民担心牧路被围。新户不认识旧界标，说自己照官给的荒地册开围栏。山民愿帮他们过冬，却希望以后仍能沿这条坡路进山。',[
('先拆哪一段栏','府署可以补地拆栏，也可维护荒地册，或先留公共牧路。两个家庭的牲畜已经挤在同一处溪边，界线需要比纸上更清楚。','补地拆栏，保留牧路。|维护荒地册，另给山民便道。|共同查界，先留溪边共用。'),
('山上第一场雪','迁户的牲畜不惯雪路，山民愿提供草料和向导。旧牧主要求新户先承认牧界，府署可以供草料，也可要求双方以救助重订冬牧约。','供草料，不以界争限救助。|承认旧牧界，换取照料。|按实际照料重订冬牧约。'),
('春天移回的围栏','新户愿照冬牧约改栏，山民请求木牌能记两种地名。书记认为一册一名便于征税，府署可承认双名，也可保留官名附注。','木牌记双名，认可共同见证。|只用官名，维持地册。|官册附旧名，教两方核对。')],['public_land g-6|estate_land g-5|witness g-3','winter_pasture grain g-6|custom p3|survey g-4 r.2','translation g-4|censor p3|school g-5'],'land'),
S('shared','','递到府署的合姓诉状','迁户与旧户一起控告一名收路钱的管事，管事说迁户不在旧乡约中，没有资格联署。旧户愿替他们担保，条件是新户日后修桥也出同样的份额。诉状因此既问收费，也问谁算这条路上的人。',[
('可不可以联署','府署可按实际住行受理，也可只认旧户联署，或先查收费凭据。管事希望在受理之前便把迁户的名字划去。','按实际住行受理所有姓名。|只认旧户联署，维持乡约。|先核收费，再议联署资格。'),
('路钱去了哪里','查账发现部分路钱确实修过桥，另一些却用在管事家中。乡老担心全部追回会使下季无人修桥，迁户请求把私用与公用分开。','追回私用，保留公用工钱。|由管事补修，保留其名望。|转入共同公账，轮派查验。'),
('新一季的路钱','管事辞去主持后，旧户请求由族老继任，新户提出按使用和出资推举。府署可承认共同主持，也可保留旧名额而公开账本。','按使用与出资共同推举。|保留旧名额，定期公开账本。|府署收管，统一路费。')],['justice p2 nobles-.03|custom p3|audit g-3','audit p2|patron p3|witness g-4','witness p2|custom p4|tolls g4'],'justice'),
S('shared','','新来的船工','外乡船工替旧船帮修好了一艘险些报废的船，船主答应给他一份跑船名额。船帮却认为资格只传本帮子弟，提议给一笔工钱代替。船工不愿永远做岸边短工，家属已在渡口租了住处。',[
('一次修船算什么','府署可按技艺认可名额，也可维护旧帮传承，或准短期随船试用。行会担心新名额会压低船费，船主则不想失去好匠人。','按技艺给试船名额。|付工钱，维护旧帮。|让船主担保限期随船。'),
('船上缺的一顿饭','试船时，新船工领到的饭钱比旧工少，船帮认为入帮前应自带口粮。家属请求承认他的实际劳作，府署可重核雇用，也可只给一次救济。','按实作补饭钱，重订雇用。|给一次救济，维持入帮规矩。|船主与船帮共同供粮。'),
('愿不愿再留一年','船工学会了本地险滩，请求正式入帮。船帮愿收，但要求他放弃旧乡的师傅称呼。府署可以承认两种传习，也可让入帮完全按旧规办理。','准入帮，保留旧师承。|按旧规入帮，维护船帮体面。|设公开试船，不按籍贯择人。')],['craft g-5 r.2|guild g-4 p3|contract burghers.02','wages g-5|grain g-4|witness g-3','translation p-1|guild p4|school g-6 r.3'],'navigation'),
S('shared','','返回旧乡的长者','一位迁来多年的长者准备回湖广祭扫，请求带走自己留下的地契副本。田主认为长期离乡会使契约失效，子女愿继续耕作。长者说回去并非舍弃新乡，但他不愿把祖先的坟地永远留在一封旧信里。',[
('回乡算不算离籍','府署可认可子女继续承契，也可按旧例暂停名额，或让家属明确担保。长者已经付过路钱，船期不能无限等待。','认子女承契，给回乡路凭。|暂停部分名额，维护旧籍。|准限期回乡，由家属共同担保。'),
('寄回来的旧信','长者从旧乡寄来一封介绍亲族的信，请求他们也能来住。族老担心一封接一封的信使户册无法控制，田主愿招来做工。','按住行记录接纳，不凭亲族独占。|限制亲族来住，保护旧户。|按工种分批接纳，限定租约。'),
('两处坟地的祭钱','长者回来后，子女请求在新乡留一处祭田，旧族认为他们的祖坟仍在外地，不应再分公地。府署可以准自购，也可只认可原有祭祀名额。','准自购祭田，承认本府住户。|保留旧族公地，按旧乡祭扫。|设共同纪念，不另分族田。')],['integration g-4 p-1|closed_register p3|witness p2','open_register g-6 p-2|closed_register p4|contract g-3','public_land p-1|custom p4|festival g-4'],'culture'),
]

def E(title,body,choices,plans,theme='justice'):
    return dict(title=title,body=body,choices=choices.split('|'),plans=plans.split('|'),theme=theme)
SOLO = [
E('入籍钱的去处','几户外来人家为入籍交过钱，来到府署却发现自己的名字仍在临住册里。书吏说钱是查验来路的费用，转入正册还需另请担保。旧户认为所有人都照此办理，新户却拿出旧收据，要求说明当初承诺的究竟是什么。\n\n掌库官希望维持这笔收入，以免以后查验无钱可用；乡老愿替长期住户见证，但不愿为刚下船的人负责。我们可以退还无据的费用，重订入籍办法，也可以保留旧担保而给穷户宽限。','退无据费用，公开入籍办法。|维护旧担保，给穷户延期。|府库供查验，按居住记录立籍。','justice g-6 p-2|custom p3|open_register g-7 nobles-.03'),
E('尚未写明的墓地','一户新来人家在山脚埋葬长者，旧村认为那片坡地留作公共牧路，请求移墓。家属说安葬时问过附近住户，没人说过这一条旧约。墓旁已经栽下小树，孩子每天都沿那条路走去。\n\n乡老提出另给葬地，费用应由迁户承担；医者提醒，近来人家接连迁入，迟早需要一处有共同规则的葬地。府署可以为迁葬出钱，也可以保护现墓、改牧路，或坚持旧界却设一次救济。','给迁葬钱，设共同葬地。|保留现墓，另补牧路。|守旧牧界，按例给家属救济。','witness g-6 nobles-.02|public_land g-5|custom grain g-4 p3','land'),
E('坊里的两种尺寸','外乡木匠按旧乡尺寸做了一批箱子，本地货主发现装不进约好的船舱。木匠愿改，却认为契纸上没有写明哪一种尺，货主坚持本地买卖当然照本地办法。学徒拿着两把尺站在仓前，不知道该把哪一种刻度磨去。\n\n府署可以共同验尺寸并补改作的钱，也可以维护本地行规，或让新匠人公开两种尺的换算。解决这批箱子只是眼前的事，以后谁能读懂契纸才会决定他们能否继续接单。','共同验尺，补改作钱。|按本地尺处理，保留行规。|刊出换算，准两种尺并用。','craft g-6 r.2|guild p3|translation g-5 r.3','craft'),
E('新户缴来的旧钱','迁户交租时带来几串从旧乡攒下的钱，收租者认为成色不足，要求重新折价。货主愿在市上按重量收，却只肯换成较少的本地钱。家属不懂两种价目的差别，担心一趟入蜀已经把多年积蓄花去大半。\n\n府署可以组织查验，公布折价，也可以维护现有收租规定，或由商人担保分期交割。公开办法会触动靠旧折价获利的人，保留旧例则使新户继续承担不熟悉市场的代价。','查验成色，公布折价。|按旧收租规定，给短期宽限。|由商人担保分期交割。','audit g-4 p-1|custom p3|witness trade g-3'),
E('城门留下的行李','一名迁来的妇人去集市卖布，被守门者扣下旧乡的路凭。守门人说路凭已经过期，家属却拿出在本府做工的工钱册。她的行李还在城门边，布贩正在等这一天的货。\n\n官署可以认可实际住行并补发路凭，也可要求继续寻找旧籍担保，或先放货再查人。新户是否能像旧户一样出入城门，会影响商人愿不愿给他们长期订单。','依住行册补发路凭。|按旧籍担保，限期补全。|先放货，以行会查验作保。','open_register p-2 nobles-.02|closed_register p3|trade g-3','commerce'),
E('外乡人刻的碑文','迁来的石工替村里刻修桥碑，习惯把出钱者与出工者并列。旧族认为出工者只是受雇，不应与祖辈供地的名字同列。石工愿改字，几个搬石人却说自己的工钱尚未付清，碑上的体面来得比现钱还早。\n\n府署可以补工钱并保留并列，也可以尊重旧碑次序，或另刻一页工账。哪一种名字留在桥头，也会让后来者知道自己的劳作能得到怎样的承认。','付清工钱，保留共同题名。|按旧次序刻碑，另给赏钱。|把工账另刻，定期更新。','public_art wages g-7 nobles-.03|patron g-4 p4|audit g-4','culture'),
E('送到新乡的嫁资','一个新户姑娘的嫁资是旧乡带来的织具，本地媒人说不如土地体面，要求家属另补银钱。男方愿接受织具，族老担心一旦承认，旧婚约上的嫁资标准也会跟着改变。\n\n府署可以认可双方自己的约定，也可以维持旧礼、给予有限资助，或安排共同见证，限制婚约之后不断追加的索取。两家已经摆好席，姑娘却仍在门后等媒人决定她带来的东西算不算足够。','认双方议定的织具嫁资。|按旧礼补钱，维持族老声名。|共同见证，禁止无据追加。','witness p-1 nobles-.03|patron g-6 p4|justice p2','culture'),
E('义仓外的一匹骡子','新来的赶马人把骡子抵给义仓换粮，约定秋后取回。掌仓人却在收粮前把骡子租给商队，回来时骡腿受伤。赶马人说那是全家沿山路谋生的牲畜，不能只按粮钱赔算。\n\n我们可以付照料费并追究借用，或保护义仓担保、给他延期还粮，也可要求商队承担治疗并重新写明抵押的使用权。仓粮与交易的信用都需要维护，牲畜的损失却已经落在一家人身上。','照料骡子，追究无约出租。|给赶马人延期，维护义仓。|商队治骡，重新订抵押。','medicine justice g-6|grain custom g-4 p3|audit g-3','veterinary'),
E('没有族人作保的匠人','一名外乡匠人申请接修城梯的活，因没有本地亲族作保而被拒。过去替他订货的商人愿担保，却要求匠人以后只为自己供货。掌工程的人称没有担保便无法追究坏工，匠人拿出的旧作品无人愿看。\n\n府署可以以实作验工，也可以维护家族担保，或允许商人作保但限定独供期限。我们所选的凭据，会使更多有手艺的人留下，也可能让旧承包者觉得自己失去了惯有的保护。','按实作验工，不限亲族。|维持旧担保，保护工程信用。|准商人作保，限定独供年数。','craft g-5 r.2 nobles-.03|custom p3|contract trade g-3','craft'),
E('小院里供的旧乡神','迁户在院中供起旧乡的神像，邻居担心他们不参加本村的共同祭礼。新户说仍会出修桥的钱，只是不愿把祖辈的祭法丢在船上。寺院愿让他们在一侧留席，条件是先承认本地祭日的次序。\n\n府署可以承认各家礼俗并限定公共责任，也可以坚持统一祭期，或促成并存的共席。新乡的规矩若只靠谁更熟悉某一种神号来决定，出钱与劳作便很难成为共同的凭据。','准旧乡礼俗，明定公共责任。|统一祭期，维护寺院主持。|安排并存共席，按出资修亭。','festival translation p-1 clergy-.03|temple p4|witness g-4','faith'),
E('被抢先收走的荒税','新户刚翻过荒地，管事便来收一整季田税，称田界已经写进官册。家属出示先前约定的免税期，管事说那是前任书记的私许。旧户希望所有田都同样交税，却也担心官府会以换任为由否认他们的旧契。\n\n府署可以认免税期，追查过早征收，也可以维护现税额、另给开垦担保，或将减免限定到真正下种的田。今天怎样解释一张旧契，也会影响整个乡里对后来约定的信任。','认免税期，退早收荒税。|维持税額，以开垦钱补助。|查实际下种，重核减免。','relief g-5 p-1|estate_land g-6 p3|audit g-4','tax'),
E('新乡来的纸伞','外乡纸户试做轻巧的油纸伞，集市客人很快买走几把。旧作坊指责他们用了不惯本地雨季的纸，要求暂停出售。纸户愿拿伞在雨中比较，商人却已经订好一批要随茶队进山的货。\n\n我们可以给试验与退货留出时间，也可以保护旧作坊的验货权，或让买主按使用路段自己选择。若新手艺只需旧行会一声反对便停下，新户可能留下田，却不会留下自己的技艺。','资助试伞，明定退货。|旧作坊验货，维护行规。|公开货样，准买主按路程选择。','survey craft g-6 r.3|guild p3|trade burghers.03','craft'),
E('抄错的出生地','一名在本府出生的少年领工牌时，册上却写着父亲的湖广旧籍。书记认为家族籍贯不因孩子出生地改变，少年请求按自己从未离开的地方登记。旧族担心年轻一代都转为本地正户后，现有名额不足分配。\n\n府署可以认本府出生与成长的记录，也可以保留家族旧籍，或以固定年数的居住办理转籍。少年的师傅已经给他留了一张工桌，工牌上的一行字却决定他能否接到长期订单。','依本府出生与成长转籍。|保留家族旧籍，维护名额。|按居住年数转籍，公开办法。','open_register p-2 nobles-.03|closed_register p4|integration audit g-3','education'),
E('新老住户一起失火','一场火烧过旧村与新户草棚，修坊的人先给有族人担保者发木料。新户没有本地宗祠，只能在空地等剩下的料。商人愿贷款重建，条件是住户日后以低价供货。\n\n府署可以按损失配料，让新旧穷户都能复屋，也可以维护族担保、给新户短期工钱，或公开重建借约，限制追加的利息。重建的次序，将使失去同样房屋的人看到不同的待遇。','按实损配料，府库担保重建。|维护族担保，另给新户工钱。|公开借约，限制无据追加。','settlement g-9 nobles-.03|wages custom g-6 p3|justice g-4','labor'),
E('该交给谁的渡口钱','几户迁来船家出过修渡钱，却仍按客船支付较高的渡费。渡口主持说出钱是自愿捐助，旧户的免渡来自祖先修桥。船家请求让自己的出资也能得到一段明确的通行权。\n\n我们可以按近期出资重订免渡，也可以保留旧权而退还部分钱，或把所有渡费与维修钱列入同一公账。今天不能总称捐助没有凭据，明天又要求这些人继续为公共渡口出钱。','按近期出资给限期免渡。|保留旧权，退部分修渡钱。|设共同公账，统一渡费。','trade nobles-.03|custom g-6 p3|audit g-4','commerce'),
E('移来的一口铁锅','一家湖广人带来一口旧铁锅，借给邻里煮共同的饭。锅裂以后，两家都说对方烧火过猛，旧乡匠人愿修，本地铁坊只肯回炉。家属不愿仅按废铁价交出它，锅上还留着几代人添补过的痕迹。\n\n府署可以为修锅出钱，比较两种技法，也可以按本地铁坊办法处理，或让两家共同订新锅、保存旧补片。小物的价钱不大，它在新乡被怎样对待却会被许多人记住。','资助修锅，比较补铁技法。|按铁坊旧例，给家属补偿。|共同订新锅，保存旧补片。','craft g-4 r.2|guild g-3 p3|festival g-4','craft'),
E('没有人领走的旧信','驿站积下几封寄给迁戶的旧信，收信人已经去世或迁到另一处。驿吏请求按例销毁，以免继续占用人手；同乡愿沿新村找人，却须先知道信封上的地名和称谓。几封信中还夹着为入蜀做准备的路钱。\n\n府署可以付路费继续查送，也可以按旧例封存，或由同乡会馆共同登记寻人。保留旧乡的联系会添一份开支，也可能让后来者找到一个更确定的落脚处。','付路费查送，登记迁居。|按例封存，维护驿站效率。|同乡共查，府署核验路钱。','translation g-5 p-1|military p3|witness audit g-3','caravan'),
E('乡册背面的名字','年末重抄乡册时，书记把暂住的迁户另列在最后几页。几个新户已经纳税多年，也参加过修桥，却仍没有参与查账的资格。族老愿把其中几位富户移到正册，不愿让所有人援用同一条办法。\n\n府署可以按居住、纳税与出资公开转籍，也可以保留族老逐案担保，或先给予查账资格，暂不更改乡册。新的共同天下究竟用什么承认一个人，将在这些看似细小的次序中留下答案。','按记录公开转籍。|由族老逐案担保，维护旧序。|先准共同查账，留转籍期限。','open_register p-3 nobles-.04|closed_register p4|audit integration g-4','justice'),
]
assert len(SHORT)==12 and len(SOLO)==18
